begin;
with j as (select * from jsonb_to_recordset($law7d0044$[{"code_id":"KoAP_RF","article_number":"7.271","version_date":"2001-12-30","article_text":"Причинение имущественного ущерба собственнику или иному владельцу имущества путем обмана или злоупотребления доверием при отсутствии признаков уголовно наказуемого деяния -\n\nвлечет наложение административного штрафа в размере до пятикратной стоимости причиненного ущерба, но не менее пяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 07.12.2011 № 420-ФЗ)","article_title":"Статья 7.271. Причинение имущественного ущерба путем обмана или злоупотребления доверием","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"897dba33f6a38bc7517903a47ae60810601ab6a7fb59bb3740a94cc6be123bac"},{"code_id":"KoAP_RF","article_number":"7.28","version_date":"2001-12-30","article_text":"Нарушение установленного порядка патентования объектов промышленной собственности в иностранных государствах -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на юридических лиц - от пятидесяти тысяч до восьмидесяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.28. Нарушение установленного порядка патентования объектов промышленной собственности в иностранных государствах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35aa4ecd9fd2ed6b67f86e1698d5876d8af2e53807c058f0a0160f21d21848fc"},{"code_id":"KoAP_RF","article_number":"7.29","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.29. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.291","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.12.2013 № 326-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.291. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ada1748afda6042d5df18810cbd8a40bcdd36b0c68359e6571596a322363084"},{"code_id":"KoAP_RF","article_number":"7.292","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.12.2013 № 326-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.292. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ada1748afda6042d5df18810cbd8a40bcdd36b0c68359e6571596a322363084"},{"code_id":"KoAP_RF","article_number":"7.293","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 03.07.2016 № 318-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.293. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2af79c3eb9c8705bb6ee187c038bec5fb81bc407551d2d9c8393109df6bc9012"},{"code_id":"KoAP_RF","article_number":"7.3","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 09.03.2021 № 38-ФЗ, от 25.12.2023 № 638-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от восьмисот тысяч до одного миллиона рублей.\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от двадцати тысяч до сорока тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей.\n\n(Статья в редакции Федерального закона от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.3. Пользование недрами без лицензии на пользование недрами либо нарушение условий, предусмотренных лицензией на пользование недрами, и (или) требований утвержденных в установленном порядке технических проектов, а также планов и схем развития горных работ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"720fe8239de28c5e48a2258e603cefc9d4fff8edd8c0823fe86c3d6f50e70038"},{"code_id":"KoAP_RF","article_number":"7.30","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.30. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.301","version_date":"2001-12-30","article_text":"1. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее - законодательство Российской Федерации и иные нормативные правовые акты о контрактной системе в сфере закупок) порядка формирования, утверждения планов-графиков закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее в настоящей статье - закупка) и внесения изменений в такие планы-графики или порядка размещения планов-графиков закупок в единой информационной системе в сфере закупок либо неразмещение плана-графика закупок в установленном законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок порядке -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей.\n\n2. Нарушение требований к закупаемым товарам, работам, услугам и (или) нормативных затрат, установленных в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок при нормировании в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей.\n\n3. Нарушение установленных в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к определению и обоснованию начальной (максимальной) цены контракта, цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), начальной цены единицы товара, работы, услуги или начальной суммы цен единиц товара, работы, услуги -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), начальной цены единицы товара, работы, услуги, начальной суммы цен единиц товара, работы, услуги, но не менее десяти тысяч и не более пятидесяти тысяч рублей.\n\n4. Выбор способа определения поставщика (подрядчика, исполнителя) с нарушением требований, установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, либо применение закрытого конкурентного способа определения поставщика (подрядчика, исполнителя) без согласования с федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации, либо проведение закрытого конкурентного способа определения поставщика (подрядчика, исполнителя) на условиях, отличных от согласованных с указанным органом, либо заключение контракта с единственным поставщиком (подрядчиком, исполнителем) в случаях, не предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, либо заключение контракта с единственным поставщиком (подрядчиком, исполнителем) без согласования с контрольным органом в сфере закупок в случаях, если необходимость такого согласования предусмотрена указанными законодательством и нормативными правовыми актами, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к содержанию документов, формируемых (составляемых) при осуществлении закупок, к порядку и сроку размещения информации и документов, за исключением случаев, предусмотренных частями 1, 2 и 9 настоящей статьи, либо неразмещение информации и документов в нарушение порядка, установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, за исключением случаев, предусмотренных частями 1 и 9 настоящей статьи, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от трех тысяч до десяти тысяч рублей.\n\n6. Действия, предусмотренные частью 5 настоящей статьи, повлекшие необоснованное ограничение количества участников закупки, -\n\nвлекут наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, но не менее десяти тысяч и не более пятидесяти тысяч рублей.\n\n7. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к рассмотрению и оценке заявки на участие в закупке, либо отклонение заявки на участие в закупке или отстранение участника закупки от участия в определении поставщика (подрядчика, исполнителя) в нарушение установленных указанными законодательством и нормативными правовыми актами требований, либо признание заявки соответствующей установленным при осуществлении закупки требованиям в случае, если такая заявка подлежит отклонению, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, но не менее пяти тысяч и не более тридцати тысяч рублей.\n\n8. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к порядку либо сроку возврата денежных средств, внесенных в качестве обеспечения заявки на участие в закупке или обеспечения исполнения контракта, за исключением случая, предусмотренного частью 4 статьи 7.306 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента суммы денежных средств, внесенных в качестве обеспечения заявки или обеспечения исполнения контракта, но не менее пяти тысяч и не более тридцати тысяч рублей.\n\n9. Нарушение заказчиком, оператором электронной площадки, оператором специализированной площадки, кредитной организацией установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к порядку либо сроку размещения информации и документов или направления их для размещения в реестрах, предусмотренных указанными законодательством и нормативными правовыми актами, либо неразмещение информации и документов или ненаправление их для размещения в реестрах, предусмотренных указанными законодательством и нормативными правовыми актами, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на юридических лиц, являющихся кредитными организациями, - от тридцати тысяч до пятидесяти тысяч рублей.\n\n10. Включение заведомо недостоверной информации в реестр недобросовестных поставщиков (подрядчиков, исполнителей) -\n\nвлечет наложение административного штрафа на должностных лиц органа, осуществляющего ведение реестра недобросовестных поставщиков (подрядчиков, исполнителей), в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n11. Осуществление закупок у субъектов малого предпринимательства, социально ориентированных некоммерческих организаций в объеме менее объема, предусмотренного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от сорока тысяч до шестидесяти тысяч рублей.\n\nПримечания:\n\n1. Если в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок при осуществлении закупки устанавливается максимальное значение цены контракта, размер административного штрафа, исчисляемого в соответствии с настоящей статьей исходя из размера начальной (максимальной) цены контракта, исчисляется от размера максимального значения цены контракта.\n\n2. Административная ответственность, установленная частью 7 настоящей статьи, не применяется, если требование, послужившее основанием для неправомерных рассмотрения и оценки заявки на участие в закупке, неправомерного отклонения заявки на участие в закупке, неправомерного отстранения участника закупки от участия в определении поставщика (подрядчика, исполнителя), неправомерного признания заявки соответствующей установленным при осуществлении закупки требованиям, установлено в извещении об осуществлении закупки, приглашении принять участие в определении поставщика (подрядчика, исполнителя), документации о закупке с нарушением законодательства Российской Федерации и иных нормативных правовых актов о контрактной системе в сфере закупок.\n\n3. Временем совершения административного правонарушения, предусмотренного частью 11 настоящей статьи, является дата окончания календарного года.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.301. Нарушение установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд порядка планирования таких закупок и определения поставщика (подрядчика, исполнителя), требований к порядку, сроку размещения информации и документов или направления их для размещения в реестрах, предусмотренных указанными законодательством и нормативными правовыми актами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ccffbc540faa2dfa7820d642ff568d5cdcf183ae0c159a85ce411a90a52a2a12"},{"code_id":"KoAP_RF","article_number":"7.302","version_date":"2001-12-30","article_text":"1. Заключение контракта по результатам определения поставщика (подрядчика, исполнителя) с нарушением условий, предусмотренных извещением об осуществлении закупки товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее в настоящей статье - закупка), приглашением принять участие в определении поставщика (подрядчика, исполнителя), документацией о закупке либо заявкой участника закупки (включая предварительное предложение о поставке товара), с которым заключен контракт, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, но не менее пяти тысяч и не более тридцати тысяч рублей; на юридических лиц - в размере 1 процента начальной (максимальной) цены контракта, но не менее пятидесяти тысяч и не более двухсот тысяч рублей.\n\n2. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к направлению или размещению проекта контракта, рассмотрению протокола разногласий, заключению контракта либо срокам осуществления таких действий -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей.\n\n3. Изменение условий контракта, если возможность изменения таких условий контракта не предусмотрена законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до трехсот тысяч рублей.\n\n4. Действия, предусмотренные частями 1 и 3 настоящей статьи, повлекшие увеличение цены контракта, дополнительное расходование средств соответствующих бюджетов бюджетной системы Российской Федерации или уменьшение количества поставляемых товаров, объема выполняемых работ, оказываемых услуг, -\n\nвлекут наложение административного штрафа на должностных лиц в размере 1 процента цены контракта, но не менее пятидесяти тысяч и не более двухсот тысяч рублей; на юридических лиц - в размере 1 процента цены контракта, но не менее двухсот тысяч и не более четырехсот тысяч рублей.\n\n5. Несоблюдение требования о проведении экспертизы поставленного товара, результатов выполненной работы, оказанной услуги или отдельных этапов исполнения контракта в случае, если в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок к проведению такой экспертизы заказчик обязан привлечь экспертов, экспертные организации, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до двадцати тысяч рублей.\n\n6. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к оформлению приемки результатов отдельного этапа исполнения контракта, поставленного товара, выполненной работы (ее результатов) или оказанной услуги либо сроков такой приемки, ненаправление мотивированного отказа от подписания документа о приемке или неприменение мер ответственности к поставщику (подрядчику, исполнителю) в случае нарушения им условий контракта -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей.\n\n7. Приемка результатов отдельного этапа исполнения контракта, поставленного товара, выполненной работы (ее результатов) или оказанной услуги при несоответствии поставленного товара, выполненной работы (ее результатов) или оказанной услуги условиям контракта в случаях, не предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента цены контракта, но не менее пятидесяти тысяч и не более двухсот тысяч рублей.\n\n8. Нарушение срока либо порядка оплаты отдельных этапов исполнения контракта, поставляемого товара, выполняемой работы (ее результатов) или оказываемой услуги, в том числе неисполнение обязанности по обеспечению авансирования, предусмотренного контрактом, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента цены контракта (этапа исполнения контракта, аванса, предусмотренного контрактом), но не менее десяти тысяч и не более пятидесяти тысяч рублей.\n\n9. Нарушение установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок порядка расторжения контракта в случае одностороннего отказа от исполнения контракта -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n10. Повторное совершение должностным лицом административного правонарушения, предусмотренного частью 4, 7 или 8 настоящей статьи, -\n\nвлечет дисквалификацию на срок от одного года до двух лет.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)\n\nатья 7.303. Нарушение порядка формирования, размещения и выполнения государственного оборонного заказа\n\n1. Нарушение установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок порядка определения начальной (максимальной) цены государственного контракта при размещении государственного оборонного заказа путем использования конкурентных способов определения поставщиков (исполнителей, подрядчиков) или цены государственного контракта в случае размещения государственного оборонного заказа у единственного поставщика (исполнителя, подрядчика) -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n2. Отказ или уклонение поставщика российских вооружения и военной техники, которые не имеют российских аналогов, единственного поставщика (исполнителя, подрядчика), определенного законодательными актами Российской Федерации, актами Президента Российской Федерации, актами Правительства Российской Федерации, от заключения государственного контракта по государственному оборонному заказу, если заключение такого государственного контракта является обязательным для указанных лиц, за исключением случаев, предусмотренных частью 3 настоящей статьи, статьей 14.31 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n3. Отказ или уклонение поставщика (исполнителя, подрядчика), занимающего в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа доминирующее положение, от заключения договора, необходимого для выполнения государственного оборонного заказа, если заключение такого договора является обязательным для указанного лица, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n4. Нарушение сроков размещения заказов на поставки товаров, выполнение работ, оказание услуг по государственному оборонному заказу, установленных Правительством Российской Федерации в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Нарушение должностным лицом государственного заказчика условий государственного контракта по государственному оборонному заказу, за исключением случаев, предусмотренных частью 8 статьи 7.302 настоящего Кодекса, либо нарушение должностным лицом военного представительства государственного заказчика предусмотренных государственным контрактом по государственному оборонному заказу или контрактом порядка и (или) сроков осуществления контроля качества или приемки военной продукции, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n6. Нарушение должностным лицом головного исполнителя поставок продукции по государственному оборонному заказу (далее в настоящей статье - головной исполнитель) условий государственного контракта по государственному оборонному заказу, касающихся количества, качества, комплектности поставляемых товаров, качества выполняемых работ, оказываемых услуг, сроков поставки товаров, выполнения работ, оказания услуг, либо нарушение должностным лицом исполнителя, участвующего в поставках продукции по государственному оборонному заказу (далее в настоящей статье - исполнитель), условий контракта, касающихся количества, качества, комплектности поставляемых товаров, качества выполняемых работ, оказываемых услуг, сроков поставки товаров, выполнения работ, оказания услуг, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n7. Нарушение должностным лицом головного исполнителя срока и (или) порядка оплаты товаров (работ, услуг), поставляемых (выполняемых, оказываемых) по государственному оборонному заказу, в том числе неисполнение обязанности по обеспечению авансирования, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от пятидесяти тысяч до ста тысяч рублей.\n\n8. Совершение головным исполнителем, исполнителем действий (бездействие), запрещенных законодательством Российской Федерации в сфере государственного оборонного заказа, если такие действия (бездействие) приводят или могут привести к необоснованному завышению цены на продукцию по государственному оборонному заказу, неисполнению или ненадлежащему исполнению государственного контракта по государственному оборонному заказу или контракта, за исключением случаев, предусмотренных частями 6, 7 и 9 настоящей статьи, статьей 14.31 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n9. Включение головным исполнителем, исполнителем в себестоимость производства (реализации) продукции по государственному оборонному заказу затрат, не связанных с ее производством (реализацией), повлекшее получение излишнего дохода в размере более одного миллиона рублей, за исключением случаев, предусмотренных статьей 14.31 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере пятидесяти тысяч рублей; на юридических лиц - от трех миллионов до пяти миллионов рублей.\n\n10. Неисполнение уполномоченным банком установленных законодательством Российской Федерации в сфере государственного оборонного заказа обязанностей при осуществлении банковского сопровождения сопровождаемой сделки, за исключением случаев, предусмотренных частью 14 настоящей статьи, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n11. Неисполнение головным исполнителем, исполнителем по государственному оборонному заказу требования о ведении раздельного учета результатов финансово-хозяйственной деятельности либо нарушение правил ведения такого учета -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей.\n\n12. Нарушение изготовителем (лицом, выполняющим функции иностранного изготовителя), поставщиком (подрядчиком, исполнителем) обязательных требований в отношении оборонной продукции (выполняемых работ, оказываемых услуг), поставляемой по государственному оборонному заказу, продукции (выполняемых работ, оказываемых услуг), используемой в целях защиты сведений, составляющих государственную тайну или относимых к охраняемой в соответствии с законодательством Российской Федерации иной информации ограниченного доступа, продукции (выполняемых работ, оказываемых услуг), сведения о которой составляют государственную тайну, продукции (выполняемых работ, оказываемых услуг) и объектов, связанных с обеспечением ядерной и радиационной безопасности в области использования атомной энергии, процессов проектирования (включая изыскания), производства, строительства, монтажа, наладки, эксплуатации, хранения, перевозки, реализации, утилизации, захоронения, связанных с обязательными требованиями в отношении указанной продукции и объектов, установленными в соответствии с законодательством Российской Федерации о техническом регулировании и законодательством Российской Федерации о стандартизации, в том числе государственными заказчиками, федеральными органами исполнительной власти, уполномоченными в области обеспечения безопасности, обороны, внешней разведки, противодействия техническим разведкам и технической защиты информации, государственного управления использованием атомной энергии, государственного регулирования безопасности при использовании атомной энергии, и (или) государственными контрактами (договорами), -\n\nвлечет наложение административного штрафа на должностных лиц в размере от сорока тысяч до пятидесяти тысяч рублей; на юридических лиц - от семисот тысяч до одного миллиона рублей.\n\n13. Ликвидация или перепрофилирование головным исполнителем без согласования с государственным заказчиком производственных мощностей, обеспечивающих поставки продукции по государственному оборонному заказу, в случае прекращения поставок такой продукции на очередной год и плановый период -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n14. Совершение уполномоченным банком операций по счету, открытому головному исполнителю, исполнителю для осуществления расчетов по государственному оборонному заказу, проведение которых по такому счету не допускается в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от ста тысяч до одного миллиона рублей.\n\n15. Непредставление или несвоевременное представление головным исполнителем или лицом, для которого в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа принятие государственного оборонного заказа обязательно, по запросу государственного заказчика либо непредставление или несвоевременное представление исполнителем или лицом, для которого в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа заключение контракта обязательно, по запросу головного исполнителя предложения о цене на продукцию по государственному оборонному заказу (в том числе обосновывающих такую цену документов) либо информации, подлежащей представлению в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей.\n\n16. Нарушение головным исполнителем, исполнителем по государственному оборонному заказу установленных в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа сроков и (или) порядка представления отчета об исполнении государственного контракта, контракта, представление которого государственному заказчику является обязательным в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до трехсот тысяч рублей.\n\nПримечание. Излишним доходом, указанным в части 9 настоящей статьи, признается доход, определяемый как разница между доходом, полученным в результате незаконных действий, предусмотренных указанной частью, и доходом, который сформировался бы без таких незаконных действий.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.302. Нарушение порядка заключения, исполнения, изменения и расторжения контракта","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90702fccc28b17b5711a85757650b3bee9012a9ba77665e2ad45ef19756c2e89"},{"code_id":"KoAP_RF","article_number":"7.304","version_date":"2001-12-30","article_text":"1. Осуществление закупки товаров, работ, услуг (далее в настоящей статье - закупка), если закупка в соответствии с законодательством Российской Федерации в сфере закупок товаров, работ, услуг отдельными видами юридических лиц (далее - законодательство Российской Федерации в сфере закупок отдельными видами юридических лиц) должна осуществляться в порядке, предусмотренном законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, в ином порядке -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n2. Нарушение заказчиком установленных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц требований к содержанию документов, формируемых (составляемых) при осуществлении закупок, либо нарушение предусмотренных указанным законодательством порядка и сроков размещения информации и документов -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от трех тысяч до десяти тысяч рублей; на юридических лиц - от десяти тысяч до тридцати тысяч рублей.\n\n3. Установление требований к участникам закупок, к закупаемым товарам, работам, услугам и (или) к условиям договора с нарушением законодательства Российской Федерации в сфере закупок отдельными видами юридических лиц либо оценка и (или) сопоставление заявок на участие в закупке с нарушением требований, предусмотренных указанным законодательством, -\n\nвлекут предупреждение или наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей; на юридических лиц - от десяти тысяч до тридцати тысяч рублей.\n\n4. Нарушение установленных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц требований к порядку либо сроку размещения информации и документов или направления их для размещения в реестрах, предусмотренных указанным законодательством, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Нарушение заказчиком установленных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц сроков заключения договора либо нарушение порядка заключения договора по результатам конкурентной закупки в электронной форме, участниками которой могут быть только субъекты малого и среднего предпринимательства, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n6. Осуществление закупок у субъектов малого и среднего предпринимательства в размере менее размера, предусмотренного законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n7. Нарушение установленного законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц срока оплаты товаров, работ, услуг по договору (отдельному этапу договора), заключенному по результатам закупки с субъектом малого или среднего предпринимательства, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.304. Нарушение порядка осуществления закупок товаров, работ, услуг отдельными видами юридических лиц","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57dc7dda6a875eacf93c0d405a84e68ec7aac925af9fc0e88bdaa2b6cf46495a"},{"code_id":"KoAP_RF","article_number":"7.305","version_date":"2001-12-30","article_text":"1. Нарушение установленных законодательством Российской Федерации требований к порядку и (или) сроку размещения информации о проведении обязательных в соответствии с законодательством Российской Федерации торгов (далее - обязательные торги), продаже государственного или муниципального имущества и (или) размещение недостоверной информации о проведении обязательных торгов, продаже государственного или муниципального имущества, за исключением случаев, предусмотренных частями 1, 5 и 9 статьи 7.301, частями 2 и 4 статьи 7.304 настоящего Кодекса, либо предоставление документации, содержащей недостоверные сведения, -\n\nвлекут наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей; на индивидуальных предпринимателей - от сорока тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n2. Нарушение порядка определения формы проведения обязательных торгов, за исключением случаев, предусмотренных частью 4 статьи 7.301, частью 1 статьи 7.304 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей; на индивидуальных предпринимателей - от сорока тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n3. Нарушение порядка предоставления документации об обязательных торгах, порядка разъяснения такой документации, порядка приема заявок на участие в обязательных торгах, заявок на участие в продаже государственного или муниципального имущества, порядка допуска к участию в обязательных торгах или порядка определения победителя обязательных торгов, продажи государственного или муниципального имущества, за исключением случаев, предусмотренных частями 5 - 7 статьи 7.301, частями 2 и 3 статьи 7.304 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на индивидуальных предпринимателей - от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей.\n\n4. Нарушение сроков заключения договоров по результатам проведения обязательных торгов, продажи государственного или муниципального имущества или в случае, если обязательные торги признаны несостоявшимися, либо уклонение организатора обязательных торгов, продавца государственного или муниципального имущества, организатора продажи государственного или муниципального имущества от заключения такого договора, за исключением случаев, предусмотренных частью 2 статьи 7.302, частью 5 статьи 7.304 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Изменение организатором обязательных торгов, продавцом государственного или муниципального имущества либо лицом, являющимся стороной договора, по соглашению сторон или в одностороннем порядке условий договора при его заключении или исполнении, установленных в документации об обязательных торгах, извещении о проведении обязательных торгов, информационном сообщении о продаже государственного или муниципального имущества, проектах договоров, в случае, если федеральным законом предусмотрен запрет такого изменения, за исключением случаев, предусмотренных частями 1, 3 и 4 статьи 7.302, частью 5 статьи 7.304, частью 1 статьи 7.306 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до трехсот тысяч рублей.\n\n6. Нарушение процедуры и (или) порядка организации и проведения обязательных торгов, продажи государственного или муниципального имущества, за исключением случаев, предусмотренных частями 1 - 5 настоящей статьи, статьями 7.301 - 7.304, 7.306 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до десяти тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.305. Нарушение процедуры обязательных в соответствии с законодательством Российской Федерации торгов, продажи государственного или муниципального имущества","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b1fa14bebc6ca6a80f225e6ced29bf2874866f6bca164e31675b200950f3dfa"},{"code_id":"KoAP_RF","article_number":"7.306","version_date":"2001-12-30","article_text":"ния закупок, предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, закупок, предусмотренных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц, и обязательных торгов в электронной форме, нарушение кредитной организацией установленного порядка блокирования и прекращения блокирования денежных средств на банковском счете участника таких закупок и (или) обязательных торгов\n\n1. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации правил документооборота при проведении закупок, предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, закупок, предусмотренных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц (далее в настоящей статье - закупки), и обязательных торгов в электронной форме, за исключением случаев, предусмотренных частями 2 - 4 настоящей статьи, -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до тридцати тысяч рублей.\n\n2. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации требований к обеспечению непрерывности проведения закупок и обязательных торгов в электронной форме, надежности функционирования программно-аппаратных средств, используемых для их проведения, равного доступа участников закупок и обязательных торгов к участию в них, неизменности подписанных усиленной квалифицированной электронной подписью документов -\n\nвлечет наложение административного штрафа в размере от ста тысяч до двухсот тысяч рублей.\n\n3. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации требований к обеспечению конфиденциальности информации при проведении закупок и обязательных торгов -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n4. Нарушение кредитной организацией установленных законодательством Российской Федерации требований к порядку и (или) сроку блокирования и прекращения блокирования денежных средств на банковском счете участника закупок и (или) обязательных торгов либо нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации требований к порядку и (или) сроку направления в кредитную организацию информации, необходимой для осуществления таких блокирования и прекращения блокирования, -\n\nвлечет предупреждение или наложение административного штрафа в размере 1 процента суммы денежных средств, подлежащих блокированию или прекращению блокирования, но не менее пяти тысяч и не более тридцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.306. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных порядков проведе","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0677c2cb323c42cb04d3fe30ac2246df31fa5242951f85eb4fab548bbdc843c2"},{"code_id":"KoAP_RF","article_number":"7.31","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.31. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.311","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 17.07.2009 № 160-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.311. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b4157495ad2c00312ae1f76e7097aeabcdc051b772d1e5841ba96d108a8a532d"},{"code_id":"KoAP_RF","article_number":"7.32","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.32. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.321","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.12.2013 № 326-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.321. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ada1748afda6042d5df18810cbd8a40bcdd36b0c68359e6571596a322363084"},{"code_id":"KoAP_RF","article_number":"7.322","version_date":"2001-12-30","article_text":"Нарушение наймодателями по договорам найма жилых помещений жилищного фонда социального использования установленных жилищным законодательством обязательных требований к заключению и исполнению таких договоров, требований к деятельности по предоставлению жилых помещений по договорам найма жилых помещений жилищного фонда социального использования либо требований, установленных в отношении количества жилых помещений и общей площади жилых помещений, которые должны быть предоставлены в наемном доме социального использования по договорам найма жилых помещений жилищного фонда социального использования, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати до пятидесяти тысяч рублей; на юридических лиц - от ста до двухсот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 21.07.2014 № 217-ФЗ)","article_title":"Статья 7.322. Нарушение требований жилищного законодательства к заключению и исполнению договоров найма жилых помещений жилищного фонда социального использования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a06bd0b7a273c3898d0d21a15b51ffdc8c79c41a53640626d86aca0b7180c9d4"},{"code_id":"KoAP_RF","article_number":"7.323","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 05.05.2014 № 122-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.323. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"927c6d10ad024d7078a195ea6f1002b381221584e9b9628e86819acb22b131c8"},{"code_id":"KoAP_RF","article_number":"7.324","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 05.10.2015 № 275-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.324. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96a0e068537607ca862019fbefaa402c8d233173028c9c1de46d335585f4c261"},{"code_id":"KoAP_RF","article_number":"7.325","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 26.07.2017 № 189-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.325. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dea0fa3e7e613ab4982a63495c44102965f86fa704f443d0b3aad0c8290c0963"},{"code_id":"KoAP_RF","article_number":"7.326","version_date":"2001-12-30","article_text":"Дача экспертом, экспертной организацией, уполномоченным представителем экспертной организации заведомо ложного экспертного заключения в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд, если это действие не содержит уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей или дисквалификацию на срок от шести месяцев до одного года; на юридических лиц - от ста тысяч до ста пятидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 27.12.2018 № 510-ФЗ)","article_title":"Статья 7.326. Заведомо ложное экспертное заключение в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45c8531fd043ffcd37db63f33bcb41730cf015f35145f0121d199de8dc7d7f15"},{"code_id":"KoAP_RF","article_number":"7.33","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 23.07.2013 № 245-ФЗ)\n\nУклонение исполнителя земляных, строительных, мелиоративных, хозяйственных или иных работ либо археологических полевых работ, осуществляемых на основании разрешения (открытого листа), от обязательной передачи государству в соответствии с законодательством Российской Федерации культурных ценностей, обнаруженных в результате проведения таких работ, если это действие не содержит уголовно наказуемого деяния, -   (В редакции Федерального закона от 23.07.2013 № 245-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч пятисот рублей; на должностных лиц - от трех тысяч до четырех тысяч рублей; на юридических лиц - от тридцати тысяч до сорока тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.07.2006 № 133-ФЗ)","article_title":"Статья 7.33. Уклонение исполнителя земляных, строительных, мелиоративных, хозяйственных или иных работ либо археологических полевых работ, осуществляемых на основании разрешения (открытого листа), от обязательной передачи государству культурных ценностей, обнаруженных в результате проведения таких работ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25f6e1e928c30ad5d9aa3dd1539cade8683e1bd11cb985a69941db752b1ad367"},{"code_id":"KoAP_RF","article_number":"7.34","version_date":"2001-12-30","article_text":"Использование земельного участка на праве постоянного (бессрочного) пользования юридическим лицом, не выполнившим в установленный федеральным законом срок обязанности по переоформлению такого права на право аренды земельного участка или по приобретению этого земельного участка в собственность, -\n\nвлечет наложение административного штрафа в размере от двадцати тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.07.2007 № 212-ФЗ) (В редакции Федерального закона от 08.03.2015 № 46-ФЗ)","article_title":"Статья 7.34. Использование земельного участка на праве постоянного (бессрочного) пользования юридическим лицом, не выполнившим в установленный федеральным законом срок обязанности по переоформлению такого права на право аренды земельного участка или по приобретению этого земельного участка в собственность","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17a4a1f4d246d3f04d703be93591d84a5633590a6e7fb14e13a6c147a21ad021"},{"code_id":"KoAP_RF","article_number":"7.35","version_date":"2001-12-30","article_text":"Нарушение государственным (муниципальным) унитарным предприятием или государственным (муниципальным) учреждением порядка согласования при совершении сделки по распоряжению государственным (муниципальным) имуществом -\n\nвлечет наложение административного штрафа на должностных лиц в размере от 1 до 10 процентов цены совершенной сделки или дисквалификацию на срок от шести месяцев до трех лет; на юридических лиц - от 10 до 20 процентов цены совершенной сделки.\n\n(Дополнение статьей - Федеральный закон от 28.11.2015 № 344-ФЗ)\n\n(Наименование в редакции Федерального закона от 13.06.2023 № 230-ФЗ)","article_title":"Статья 7.35. Нарушение порядка согласования при совершении сделки по распоряжению государственным (муниципальным) имуществом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43924f63a664378d54617e11a6d6ab770092bb77dc6b73089c3d62be49612c61"},{"code_id":"KoAP_RF","article_number":"7.4","version_date":"2001-12-30","article_text":"Застройка площадей залегания полезных ископаемых, в том числе размещение в местах их залегания подземных сооружений без разрешения, необеспечение сохранности зданий, сооружений, а также особо охраняемых территорий и объектов окружающей среды при пользовании недрами -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n(Статья в редакции Федерального закона от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.4. Самовольная застройка площадей залегания полезных ископаемых","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e938854a8d79ba4d61d2bb5ee7236750b1451a6e448388bf36de5a8508480cd3"},{"code_id":"KoAP_RF","article_number":"7.5","version_date":"2001-12-30","article_text":"Самовольная добыча янтаря, нефрита или иных полудрагоценных камней, либо транспортировка или хранение в целях сбыта незаконно добытых янтаря, нефрита или иных полудрагоценных камней в натуральном или переработанном виде, либо сбыт незаконно добытых янтаря, нефрита или иных полудрагоценных камней в натуральном или переработанном виде, если такие действия не содержат уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на граждан в размере от двухсот тысяч до пятисот тысяч рублей с конфискацией орудия совершения административного правонарушения либо без таковой; на должностных лиц - от пятисот тысяч до восьмисот тысяч рублей с конфискацией орудия совершения административного правонарушения либо без таковой; на юридических лиц - от десяти миллионов до шестидесяти миллионов рублей с конфискацией орудия совершения административного правонарушения либо без таковой.\n\nПримечание. Перечень полудрагоценных камней в целях настоящей статьи устанавливается Правительством Российской Федерации.\n\n(Статья в редакции Федерального закона от 20.12.2017 № 414-ФЗ)","article_title":"Статья 7.5. Самовольная добыча янтаря, нефрита или иных полудрагоценных камней","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0066c857e38a3671167b67a8546a0c9f4e8d2a208258e7627adf8363825c306"},{"code_id":"KoAP_RF","article_number":"7.6","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 03.06.2006 № 73-ФЗ)\n\nСамовольное занятие водного объекта или его части, либо использование их без документов, на основании которых возникает право пользования водным объектом или его частью, либо водопользование с нарушением его условий -  (В редакции Федерального закона от 03.06.2006 № 73-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до трех тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до тридцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции Федерального закона от 21.10.2013 № 275-ФЗ)","article_title":"Статья 7.6. Самовольное занятие водного объекта или пользование им с нарушением установленных условий","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35dbec7e1752c1968b4be9d90c50391031db2c49022a93cdfc4312a76fb47932"},{"code_id":"KoAP_RF","article_number":"7.7","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nПовреждение объектов и систем водоснабжения, водоотведения, гидротехнических сооружений, устройств и установок водохозяйственного и водоохранного назначения -  (В редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.7. Повреждение объектов и систем водоснабжения, водоотведения, гидротехнических сооружений, устройств и установок водохозяйственного и водоохранного назначения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecb1729af3f404c148641e45b3f6bd60536c8d7a451a56cfebad9982ad570233"},{"code_id":"KoAP_RF","article_number":"7.8","version_date":"2001-12-30","article_text":"(Статья утратила силу - Федеральный закон от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.8. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7689ee01a0f30e103ab666160c8cf8f00ee1207250f6aab3a495996723dc7614"},{"code_id":"KoAP_RF","article_number":"7.9","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\nСамовольное занятие лесных участков или использование указанных участков для раскорчевки, переработки лесных ресурсов, устройства складов, возведения построек (строительства), распашки и других целей без специальных разрешений на использование указанных участков -  (В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до пятидесяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.  (В редакции Федерального закона от 08.03.2015 № 46-ФЗ)","article_title":"Статья 7.9. Самовольное занятие лесных участков","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e1261c487e0d215142bd239a3be11929dfec5fe94cfdd7e06eb25eb0209ef6b"},{"code_id":"KoAP_RF","article_number":"8.1","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 28.12.2009 № 380-ФЗ)\n\nНесоблюдение экологических требований при территориальном планировании, градостроительном зонировании, планировке территории, архитектурно-строительном проектировании, строительстве, капитальном ремонте, реконструкции, вводе в эксплуатацию, эксплуатации, выводе из эксплуатации зданий, строений, сооружений и иных объектов капитального строительства, за исключением случаев, предусмотренных статьей 8.48 настоящего Кодекса, - (В редакции федеральных законов от 28.12.2009 № 380-ФЗ, от 27.12.2019 № 504-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей; на юридических лиц - от двадцати тысяч до ста тысяч рублей.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ; от 22.06.2007 № 116-ФЗ; от 27.07.2010 № 239-ФЗ)","article_title":"Статья 8.1. Несоблюдение экологических требований при осуществлении градостроительной деятельности и эксплуатации предприятий, сооружений или иных объектов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd73a0f0beb8898f812b5e7b4fcf38b9d24e640869de624c8901bd7f4f018491"}]$law7d0044$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
